pub fn split_borrowed(&mut self, at: usize) -> FixedVec<'_, T> {
    assert!(at <= self.capacity(), "`at` out of bounds");

    let new_uninit = self.uninit.split_at(at).unwrap();
    let new_len = at;

    // Update the length of the current FixedVec
    self.set_len(new_len);

    // Return a new FixedVec borrowing the memory
    FixedVec {
        uninit: new_uninit,
        length: self.length - new_len,
    }
}

